//! ➖️ Native removal retains the original lookup, shifted pages and removed row until paid handoff.
use super::*;
use super::edit_input::{EditInput,EditWorkspace};
use super::edit_retirement::{CloseRoute,close_key};
use crate::retained_clone::{OriginalEffectReply,OriginalEffectReplyComplete,OriginalRetirementCloseLoan};
use std::mem::ManuallyDrop;
type Reply<'r>=OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>;
type Complete<'r>=OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>;
type Effect<'a>=crate::RetainedAllocationEffect<'a>;
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
pub struct RetainedOrderedMapRemoveGrant{pub retirement:RetainedCloneGrant,pub comparison:BoundedOrdGrant,pub maximum_moved_items:usize,pub maximum_moved_bytes:usize}
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
pub struct RetainedOrderedMapRemoveProgress{pub retirement:RetainedCloneProgress,pub comparison:BoundedOrdProgress,pub moved_items:usize,pub moved_bytes:usize}
impl RetainedOrderedMapRemoveProgress{pub fn fits(self,g:RetainedOrderedMapRemoveGrant)->bool{self.retirement.fits(g.retirement)&&self.comparison.fits(g.comparison)&&self.moved_items<=g.maximum_moved_items&&self.moved_bytes<=g.maximum_moved_bytes}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedOrderedMapRemoveStep{Progress(RetainedOrderedMapRemoveProgress),Complete{removed:bool,progress:RetainedOrderedMapRemoveProgress}}
impl RetainedOrderedMapRemoveStep{pub fn progress(self)->RetainedOrderedMapRemoveProgress{match self{Self::Progress(p)|Self::Complete{progress:p,..}=>p}}}
struct State<K:BoundedOrd+RetireOwned,V:RetireOwned+Sync>{
 input:EditInput<K,V>,workspace:Option<EditWorkspace<K,V>>,lookup_result:Option<RetainedOrderedMapLookup>,
 map:Option<RetainedOrderedMap<K,V>>,key:Option<K>,removed:Option<(K,V)>,page:Option<Vec<(K,V)>>,
 target:Option<usize>,shift:usize,phase:u8,found:bool,closing:bool,spent:bool,close:RetainedCloneClose,close_route:Option<CloseRoute>,movement:RetainedOrderedMapRemoveProgress,
}
/// 🪦️ Retains actual unpublished owners through denied movement and cancelled page propagation.
pub struct RetainedOrderedMapRemoveCursor<K:BoundedOrd+RetireOwned,V:RetireOwned+Sync>{state:ManuallyDrop<State<K,V>>}
impl<K:BoundedOrd+RetireOwned,V:RetireOwned+Sync> RetainedOrderedMapRemoveCursor<K,V>{
 pub fn new(map:RetainedOrderedMap<K,V>,key:K)->Self{Self{state:ManuallyDrop::new(State{input:EditInput::new(map,key,None),workspace:None,lookup_result:None,map:None,key:None,removed:None,page:None,target:None,shift:0,phase:0,found:false,closing:false,spent:false,close:RetainedCloneClose::vacant(),close_route:None,movement:Default::default()})}}
 fn invalid()->ValueError{ValueError::invariant("native removal changed its original ownership")}
 fn overflow()->ValueError{ValueError::literal(crate::ValueRefusalKind::OwnershipLimit,"native removal extent overflow")}
 fn fixed(bytes:usize)->crate::RetirementDemand{crate::RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()}}
 fn quote(d:crate::RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
 fn funded(effect:&Effect<'_>,d:crate::RetirementDemand,work:u64)->Result<bool,ValueError>{Ok(retained_clone_grant_admits(effect.grant(),d)&&effect.remaining_work_units()?>=work)}
 fn unpack_demand()->crate::RetirementDemand{Self::fixed(size_of::<Option<EditWorkspace<K,V>>>()+size_of::<EditWorkspace<K,V>>()+size_of::<Option<RetainedOrderedMap<K,V>>>()+size_of::<Option<K>>()+size_of::<Option<RetainedOrderedMapLookup>>()+size_of::<Option<usize>>()+size_of::<bool>()+size_of::<u8>())}
 fn prefix_demand(&self,comparison:BoundedOrdGrant,body:usize)->Result<crate::RetirementDemand,ValueError>{let s=&*self.state;if s.workspace.is_some(){Ok(Self::unpack_demand())}else if s.input.ready(){s.input.take_demand()}else{s.input.next_demand(comparison,body)}}
 pub fn birth_complete(&self)->bool{self.state.phase!=0||self.state.input.birth_complete()}
 pub fn next_advance_demands(&self,body:usize)->Result<RetainedOrderedMapRemoveGrant,ValueError>{let s=&*self.state;if s.closing||s.spent||s.close_route.is_some(){return Err(Self::invalid())}let mut g=RetainedOrderedMapRemoveGrant::default();match s.phase{0=>{g.comparison=BoundedOrdGrant{maximum_items:1,maximum_bytes:body.min(64)};g.retirement=Self::quote(self.prefix_demand(g.comparison,body)?);},2=>{let map=s.map.as_ref().ok_or_else(Self::invalid)?;let index=s.target.ok_or_else(Self::invalid)?;let page=map.pages.get(index/RETAINED_ORDERED_MAP_PAGE_CAPACITY).ok_or_else(Self::invalid)?;let slot=index%RETAINED_ORDERED_MAP_PAGE_CAPACITY;if slot>=page.len(){return Err(Self::invalid())}g.maximum_moved_items=page.len()-slot;g.maximum_moved_bytes=g.maximum_moved_items.checked_mul(size_of::<(K,V)>()).ok_or_else(Self::overflow)?;},3=>{let map=s.map.as_ref().ok_or_else(Self::invalid)?;if s.shift+1<map.pages.len(){g.maximum_moved_items=map.pages[s.shift+1].len().checked_add(1).ok_or_else(Self::overflow)?;g.maximum_moved_bytes=g.maximum_moved_items.checked_mul(size_of::<(K,V)>()).ok_or_else(Self::overflow)?;}else{g.maximum_moved_items=1;}},4=>{g.maximum_moved_items=1;g.maximum_moved_bytes=size_of::<usize>()+size_of::<Vec<(K,V)>>();},5=>{},_=>return Err(Self::invalid())}Ok(g)}
 pub fn advance_demands(&self,body:usize,g:RetainedOrderedMapRemoveGrant)->Result<crate::RetirementDemand,ValueError>{let s=&*self.state;if s.closing||s.spent||s.close_route.is_some(){return Err(Self::invalid())}if s.phase==0{return self.prefix_demand(g.comparison,body)}if s.phase==5{return Ok(Default::default())}let plan=self.next_advance_demands(body)?;let metadata=match s.phase{2=>size_of::<Option<(K,V)>>()+size_of::<Vec<(K,V)>>()+size_of::<usize>()+size_of::<u8>(),3 if plan.maximum_moved_bytes!=0=>2*size_of::<Vec<(K,V)>>()+size_of::<usize>(),3=>size_of::<u8>(),4=>size_of::<Option<Vec<(K,V)>>>()+size_of::<Vec<Vec<(K,V)>>>()+size_of::<u8>(),_=>return Err(Self::invalid())};Ok(Self::fixed(plan.maximum_moved_bytes.checked_add(metadata).and_then(|n|n.checked_add(size_of::<RetainedOrderedMapRemoveProgress>())).ok_or_else(Self::overflow)?))}
 pub fn advance_work_demand(&self,body:usize,g:RetainedOrderedMapRemoveGrant)->Result<u64,ValueError>{self.advance_demands(body,g)?;let s=&*self.state;if s.phase==0&&s.workspace.is_none()&&!s.input.ready(){s.input.next_work_demand(g.comparison,body)}else{Ok(u64::from(s.phase!=5))}}
 pub fn advance_into<'r>(&mut self,body:usize,g:RetainedOrderedMapRemoveGrant,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.advance_dispatch(body,g,None,effect,reply,false)}
 pub fn recover_advance_into<'r>(&mut self,body:usize,g:RetainedOrderedMapRemoveGrant,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.advance_dispatch(body,g,None,effect,reply,true)}
 pub fn advance_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,g:RetainedOrderedMapRemoveGrant,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.advance_dispatch(body,g,Some(original),effect,reply,false)}
 pub fn recover_advance_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,g:RetainedOrderedMapRemoveGrant,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.advance_dispatch(body,g,Some(original),effect,reply,true)}
 fn advance_dispatch<'r>(&mut self,body:usize,g:RetainedOrderedMapRemoveGrant,original:Option<&mut OriginalRetirementCloseLoan<'_>>,effect:&mut Effect<'_>,reply:Reply<'r>,recover:bool)->Result<Complete<'r>,ValueError>{
  self.state.input.validate(effect)?;if self.state.closing||self.state.spent||self.state.close_route.is_some(){return Err(Self::invalid())}if recover{if self.state.phase!=0{return Err(Self::invalid())}return self.state.input.advance_into(g.comparison,body,original,effect,reply.progress(),true)}
  let d=self.advance_demands(body,g)?;let units=self.advance_work_demand(body,g)?;if !Self::funded(effect,d,units)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if self.state.phase==0{if !retained_clone_grant_admits(g.retirement,d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let s=&mut*self.state;if let Some(workspace)=s.workspace.as_ref(){if workspace.value.is_some()||s.lookup_result.is_none(){return Err(Self::invalid())}if !effect.performed(1)?{return Err(Self::invalid())}let EditWorkspace{map,key,value:_}=s.workspace.take().expect("original removal workspace");s.map=Some(map);s.key=Some(key);match s.lookup_result.take().expect("original lookup result"){RetainedOrderedMapLookup::Found(index)=>{s.target=Some(index);s.found=true;s.phase=2;},RetainedOrderedMapLookup::Missing(_)=>{s.found=false;s.phase=5;}}return Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}if s.input.ready(){return s.input.take_into(&mut s.workspace,&mut s.lookup_result,effect,reply.progress())}return s.input.advance_into(g.comparison,body,original,effect,reply.progress(),false)}
  if self.state.phase==5{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let plan=self.next_advance_demands(body)?;if g.maximum_moved_items<plan.maximum_moved_items||g.maximum_moved_bytes<plan.maximum_moved_bytes{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Err(Self::invalid())}let s=&mut*self.state;let movement=RetainedOrderedMapRemoveProgress{moved_items:if s.phase==3&&plan.maximum_moved_bytes==0{0}else{plan.maximum_moved_items},moved_bytes:plan.maximum_moved_bytes,..Default::default()};match s.phase{2=>{let map=s.map.as_mut().ok_or_else(Self::invalid)?;let index=s.target.ok_or_else(Self::invalid)?;let page=index/RETAINED_ORDERED_MAP_PAGE_CAPACITY;s.removed=Some(map.pages[page].remove(index%RETAINED_ORDERED_MAP_PAGE_CAPACITY));s.shift=page;s.phase=3;},3=>{let map=s.map.as_mut().ok_or_else(Self::invalid)?;if s.shift+1<map.pages.len(){if map.pages[s.shift].len()>=map.pages[s.shift].capacity()||map.pages[s.shift+1].is_empty(){return Err(Self::invalid())}let entry=map.pages[s.shift+1].remove(0);map.pages[s.shift].push(entry);s.shift+=1;}else{s.phase=4;}},4=>{let map=s.map.as_mut().ok_or_else(Self::invalid)?;map.len=map.len.checked_sub(1).ok_or_else(Self::invalid)?;if map.pages.last().is_some_and(Vec::is_empty){s.page=map.pages.pop();}s.phase=5;},_=>return Err(Self::invalid())}s.movement=movement;let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};Ok(reply.complete(Ok(if s.phase==5{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})))
 }
 pub fn output_ready(&self)->bool{self.state.phase==5&&self.state.map.is_some()&&!self.state.closing&&!self.state.spent}
 pub fn removed(&self)->Option<bool>{(self.state.phase==5).then_some(self.state.found)}
 pub fn comparison_progress(&self)->BoundedOrdProgress{self.state.input.comparison_progress()}
 pub fn movement_progress(&self)->RetainedOrderedMapRemoveProgress{self.state.movement}
 pub fn take_output_demand(&self)->crate::RetirementDemand{Self::fixed(2*size_of::<Option<RetainedOrderedMap<K,V>>>()+size_of::<bool>())}
 pub fn take_output_work_demand(&self)->u64{1}
 pub fn take_into<'r>(&mut self,output:&mut Option<RetainedOrderedMap<K,V>>,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.state.input.validate(effect)?;if !self.output_ready()||output.is_some(){return Err(Self::invalid())}let d=self.take_output_demand();if !Self::funded(effect,d,1)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Err(Self::invalid())}*output=self.state.map.take();self.state.spent=true;Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 pub fn begin_close_demand(&self)->crate::RetirementDemand{Self::fixed(usize::from(!self.state.closing)*size_of::<bool>())}
 pub fn begin_close_work_demand(&self)->u64{u64::from(!self.state.closing)}
 pub fn begin_close_into<'r>(&mut self,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.state.input.validate(effect)?;if self.state.close_route.is_some()||self.state.input.has_pending(){return Err(Self::invalid())}let d=self.begin_close_demand();if !Self::funded(effect,d,self.begin_close_work_demand())?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if self.state.closing{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Err(Self::invalid())}self.state.closing=true;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 pub fn close_demands(&self,body:usize)->Result<crate::RetirementDemand,ValueError>{let s=&*self.state;if let Some(route)=s.close_route{if route.key.body!=body{return Err(Self::invalid())}return Ok(route.demand)}if !s.closing{if s.input.has_pending(){return Err(Self::invalid())}return Ok(self.begin_close_demand())}if !s.close.is_empty(){return s.close.next_owner_demands::<K>(false,&None,body)}if s.lookup_result.is_some(){return Ok(Self::fixed(size_of::<Option<RetainedOrderedMapLookup>>()))}if s.workspace.is_some(){return s.close.next_owner_demands::<EditWorkspace<K,V>>(true,&None,body)}if s.key.is_some(){return s.close.next_owner_demands::<K>(true,&None,body)}if s.removed.is_some(){return s.close.next_owner_demands::<(K,V)>(true,&None,body)}if s.page.is_some(){return s.close.next_owner_demands::<Vec<(K,V)>>(true,&None,body)}if s.map.is_some(){return s.close.next_owner_demands::<RetainedOrderedMap<K,V>>(true,&None,body)}s.input.close_demand(body)}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{let s=&*self.state;if let Some(route)=s.close_route{if route.key.body!=body{return Err(Self::invalid())}return Ok(route.work)}if !s.closing{return Ok(self.begin_close_work_demand())}if !s.close.is_empty(){return s.close.next_owner_work::<K>(false,&None,body)}if s.lookup_result.is_some(){return Ok(1)}if s.workspace.is_some(){return s.close.next_owner_work::<EditWorkspace<K,V>>(true,&None,body)}if s.key.is_some(){return s.close.next_owner_work::<K>(true,&None,body)}if s.removed.is_some(){return s.close.next_owner_work::<(K,V)>(true,&None,body)}if s.page.is_some(){return s.close.next_owner_work::<Vec<(K,V)>>(true,&None,body)}if s.map.is_some(){return s.close.next_owner_work::<RetainedOrderedMap<K,V>>(true,&None,body)}s.input.close_work_demand(body)}
 pub fn close_into<'r>(&mut self,body:usize,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.close_dispatch(body,None,effect,reply,false)}
 pub fn recover_close_into<'r>(&mut self,body:usize,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.close_dispatch(body,None,effect,reply,true)}
 pub fn close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.close_dispatch(body,Some(original),effect,reply,false)}
 pub fn recover_close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut Effect<'_>,reply:Reply<'r>)->Result<Complete<'r>,ValueError>{self.close_dispatch(body,Some(original),effect,reply,true)}
 pub(super) fn close_dispatch<'r>(&mut self,body:usize,mut original:Option<&mut OriginalRetirementCloseLoan<'_>>,effect:&mut Effect<'_>,reply:Reply<'r>,recover:bool)->Result<Complete<'r>,ValueError>{self.state.input.validate(effect)?;if !recover&&!self.state.closing{return self.begin_close_into(effect,reply)}if self.terminal_is_empty(){return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let key=close_key(body,original.as_deref_mut(),effect,recover)?;let route=if recover{let route=self.state.close_route.ok_or_else(Self::invalid)?;if route.key!=key{return Err(Self::invalid())}route}else{if self.state.close_route.is_some(){return Err(Self::invalid())}let d=self.close_demands(body)?;let work=self.close_work_demand(body)?;if !Self::funded(effect,d,work)?{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let s=&mut*self.state;if s.close.is_empty()&&s.lookup_result.is_some(){if !effect.performed(1)?{return Err(Self::invalid())}s.lookup_result=None;return Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}if s.close.is_empty(){macro_rules! begin{($field:ident)=>{if s.$field.is_some(){let turn=s.close.begin_granted(&mut s.$field,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))}};}begin!(workspace);begin!(key);begin!(removed);begin!(page);begin!(map);}CloseRoute{key,operation:u8::from(!s.close.is_empty()),demand:d,work}};let s=&mut*self.state;let mut scope=reply.progress().scope(&mut s.close_route,route)?;let done=if route.operation==1{match(original,recover){(None,false)=>s.close.step_into(body,effect,scope.borrow()?),(None,true)=>s.close.recover_step_into(body,effect,scope.borrow()?),(Some(original),false)=>s.close.step_original_into(original,body,effect,scope.borrow()?),(Some(original),true)=>s.close.recover_step_original_into(original,body,effect,scope.borrow()?)}}else{s.input.close_into(body,original,effect,scope.borrow()?,recover)}?;drop(done);Ok(scope.forwarded())}
 pub fn requires_original_birth(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_birth()}else{self.state.input.requires_original_birth()}}
 pub fn requires_original_control(&self)->bool{if !self.state.close.is_empty(){self.state.close.requires_original_control()}else{self.state.input.requires_original_control()}}
 pub fn close_original_birth_step(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->crate::OriginalRetirementPoll{if !self.state.close.is_empty(){self.state.close.step_original_birth(original,grant)}else{self.state.input.original_birth_step(original,grant)}}
 pub fn terminal_is_empty(&self)->bool{let s=&*self.state;s.closing&&s.close_route.is_none()&&s.input.terminal_is_empty()&&s.workspace.is_none()&&s.lookup_result.is_none()&&s.map.is_none()&&s.key.is_none()&&s.removed.is_none()&&s.page.is_none()&&s.close.is_empty()}
}
impl<K:BoundedOrd+RetireOwned,V:RetireOwned+Sync> Drop for RetainedOrderedMapRemoveCursor<K,V>{fn drop(&mut self){if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.state)}}else if !std::thread::panicking(){panic!("native removal retains original owners")}}}
